#!/usr/bin/env python3
"""Reproducible planning assumptions; no actual sales or current verified fees."""
import argparse,csv,json,math
from pathlib import Path
TARGETS=[1000,5000,10000,20000,25000]
SCENARIOS={
 'conservative':dict(price=39,refund_rate=.08,fee_rate=.035,fee_fixed=.30,cac=22,conversion=.008,fixed=150,hosting=0,ai=0,subscriptions=150,support_per_order=2),
 'moderate':dict(price=49,refund_rate=.04,fee_rate=.029,fee_fixed=.30,cac=12,conversion=.02,fixed=100,hosting=0,ai=0,subscriptions=100,support_per_order=1),
 'optimistic':dict(price=59,refund_rate=.02,fee_rate=.029,fee_fixed=.30,cac=8,conversion=.035,fixed=100,hosting=0,ai=0,subscriptions=100,support_per_order=.50),
}
def calculate(s,target):
 if not math.isfinite(target) or target<0:raise ValueError('target must be finite and nonnegative')
 if any(not isinstance(v,(int,float)) or not math.isfinite(v) for v in s.values()):raise ValueError('assumptions must be finite numbers')
 if not 0<=s['fee_rate']<=1:raise ValueError('fee rate must be in [0,1]')
 if not 0<s['conversion']<=1:raise ValueError('conversion must be in (0,1]')
 if not 0<=s['refund_rate']<1:raise ValueError('refund must be in [0,1)')
 if min(s[k] for k in ['price','fee_rate','fee_fixed','cac','fixed','support_per_order','hosting','ai','subscriptions'])<0:raise ValueError('negative assumption')
 retained=s['price']*(1-s['refund_rate'])
 if not math.isclose(s['fixed'],s['hosting']+s['ai']+s['subscriptions'],abs_tol=1e-9):raise ValueError('fixed must equal hosting + ai + subscriptions (include other fixed costs in subscriptions reserve)')
 # Assume fees on every initial order, including refunded orders: conservative.
 fees=s['price']*s['fee_rate']+s['fee_fixed']
 contribution=retained-fees-s['cac']-s['support_per_order']
 units=None if contribution<=0 else math.ceil((target+s['fixed'])/contribution)
 return dict(target_profit=target,contribution_per_order=round(contribution,4),contribution_margin=round(contribution/s['price'],4) if s['price'] else None,orders=units,sessions=None if units is None else math.ceil(units/s['conversion']),gross_sales=None if units is None else round(units*s['price'],2),ad_budget=None if units is None else round(units*s['cac'],2),operating_profit=None if units is None else round(units*contribution-s['fixed'],2),break_even_orders=None if contribution<=0 else math.ceil(s['fixed']/contribution),implied_cost_per_click=round(s['cac']*s['conversion'],4))
def main():
 p=argparse.ArgumentParser();p.add_argument('--output-dir',default=str(Path(__file__).parent));p.add_argument('--assumptions',help='JSON object replacing scenario dictionary');args=p.parse_args()
 scenarios=json.loads(Path(args.assumptions).read_text()) if args.assumptions else SCENARIOS
 out=Path(args.output_dir);out.mkdir(parents=True,exist_ok=True)
 results=[dict(scenario=name,**calculate(s,t)) for name,s in scenarios.items() for t in TARGETS]
 for name,rows in [('scenarios',results),('sensitivity',[dict(cac=c,conversion=v,**calculate(dict(scenarios.get('moderate',next(iter(scenarios.values()))),cac=c,conversion=v),5000)) for c in [5,10,15,20,30,45] for v in [.005,.01,.02,.04]])]:
  with (out/(name+'.csv')).open('w',newline='') as f:
   w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
 (out/'assumptions.json').write_text(json.dumps(scenarios,indent=2)+'\n')
 table='\n'.join(f"| {r['scenario']} | ${int(r['target_profit']):,} | {r['orders'] if r['orders'] is not None else 'Unreachable'} | {r['sessions'] if r['sessions'] is not None else 'Unreachable'} | {r['ad_budget'] if r['ad_budget'] is not None else 'Unreachable'} |" for r in results)
 (out/'RESULTS.md').write_text('# Hypothetical monthly profit targets\n\nGenerated by `model.py`; every input is an assumption, not evidence of sales.\n\n| Scenario | Target USD | Paid orders | Sessions | Acquisition USD |\n|---|---:|---:|---:|---:|\n'+table+'\n\nOwner earnings differ from operating profit; income tax, owner compensation, development labor, chargebacks and currency costs are excluded. Annual $200,000–$300,000 owner earnings are a target, not an inference from these scenarios. Demand and sufficient qualified traffic are unvalidated.\n')
 print(json.dumps(results,indent=2))
if __name__=='__main__':main()
